window.RF_FULL=window.RF_FULL||{};window.RF_FULL["plenum5-2005"]=[
["0","Преамбула","","","О НЕКОТОРЫХ ВОПРОСАХ, ВОЗНИКАЮЩИХ У СУДОВ ПРИ ПРИМЕНЕНИИ КОДЕКСА РОССИЙСКОЙ ФЕДЕРАЦИИ ОБ АДМИНИСТРАТИВНЫХ ПРАВОНАРУШЕНИЯХ Обсудив материалы проведенного изучения практики рассмотрения судами дел, связанных с применением Кодекса Российской Федерации об административных правонарушениях, в целях обеспечения единообразия судебной практики и в связи с возникающими у судов при рассмотрении данной категории дел неясными вопросами Пленум Верховного Суда Российской Федерации постановляет дать судам следующие разъяснения:"],
["1","К законодательству об административных правонарушениях, которым следует руководствоваться при рассмотрении данной категории дел, относится Кодекс…","","","1. К законодательству об административных правонарушениях, которым следует руководствоваться при рассмотрении данной категории дел, относится Кодекс Российской Федерации об административных правонарушениях (далее - КоАП РФ), введенный в действие с 1 июля 2002 г., который определяет условия и основания административной ответственности, виды административных наказаний, порядок производства по делам об административных правонарушениях, в том числе подведомственность и подсудность этих дел, а также законы субъектов Российской Федерации, принимаемые в соответствии с КоАП РФ по вопросам, отнесенным к компетенции субъектов Российской Федерации.\nВ случае привлечения к ответственности, предусмотренной нормами Налогового кодекса Российской Федерации (НК РФ), содержащими признаки административного правонарушения, производство по делу должно осуществляться в порядке, предусмотренном КоАП РФ (часть 3 статьи 1.7 КоАП РФ, часть 2 статьи 10 НК РФ).\nПрименению подлежат только те законы субъектов Российской Федерации, которые приняты с учетом положений статьи 1.3 КоАП РФ, определяющих предметы ведения и исключительную компетенцию Российской Федерации, а также статьи 1.3.1 КоАП РФ, определяющих предметы ведения субъектов Российской Федерации. В частности, законом субъекта Российской Федерации не может быть установлена административная ответственность за нарушение правил и норм, предусмотренных законами и другими нормативными актами Российской Федерации. В качестве мер административного наказания могут быть предусмотрены предупреждение и административный штраф в размере, установленном абзацем первым части 3 статьи 3.5 КоАП РФ.\nВ случае, когда международным договором Российской Федерации установлены иные правила, чем предусмотренные законодательством об административных правонарушениях, применяются нормы международного договора, имеющие прямое и непосредственное действие в правовой системе Российской Федерации. При этом необходимо учитывать разъяснения, данные Пленумом Верховного Суда Российской Федерации в Постановлении от 10 октября 2003 г. N 5 \"О применении судами общепризнанных принципов и норм международного права и международных договоров Российской Федерации\"."],
["2","При подготовке к рассмотрению дела об административном правонарушении судья обязан произвести перечисленные в статье 29.1 КоАП РФ процессуальные…","","","2. При подготовке к рассмотрению дела об административном правонарушении судья обязан произвести перечисленные в статье 29.1 КоАП РФ процессуальные действия в целях выполнения предусмотренных статьей 24.1 КоАП РФ задач всестороннего, полного, объективного и своевременного выяснения обстоятельств каждого дела, разрешения его в соответствии с законом, а также выявления причин и условий, способствовавших совершению административного правонарушения."],
["3","При подготовке дела судье следует установить, относится ли к его компетенции рассмотрение данного дела","","","3. При подготовке дела судье следует установить, относится ли к его компетенции рассмотрение данного дела.\nПри решении вопроса о подведомственности и подсудности судьям судов общей юрисдикции дел об административных правонарушениях необходимо исходить из положений, закрепленных в главе 23 КоАП РФ, согласно которым к компетенции судей отнесены дела, перечисленные в части 1 статьи 23.1 КоАП РФ, учитывая при этом следующее:\nа) судьи районных судов рассматривают дела об административных правонарушениях, указанных в частях 1 и 2 статьи 23.1 КоАП РФ, в том случае, когда по делу проводилось административное расследование (статья 28.7 КоАП РФ) либо когда санкция статьи, устанавливающей ответственность за административное правонарушение, предусматривает возможность назначения наказания в виде административного выдворения за пределы Российской Федерации, административное приостановление деятельности или дисквалификацию лиц, замещающих должности федеральной государственной гражданской службы, должности государственной гражданской службы субъекта Российской Федерации, должности муниципальной службы (абзац второй части 3 статьи 23.1 КоАП РФ).\nВопрос о проведении административного расследования решается при возбуждении дела об административном правонарушении лицами, указанными в части 2 статьи 28.7 КоАП РФ. Административное расследование вправе проводить должностные лица, перечисленные в части 4 статьи 28.7 КоАП РФ, а также прокурор (пункт 2 статьи 1 Федерального закона \"О прокуратуре Российской Федерации\"). При этом необходимо учитывать, что административное расследование допускается только при выявлении административных правонарушений в отраслях законодательства, перечисленных в части 1 статьи 28.7 КоАП РФ.\nАдминистративное расследование представляет собой комплекс требующих значительных временных затрат процессуальных действий указанных выше лиц, направленных на выяснение всех обстоятельств административного правонарушения, их фиксирование, юридическую квалификацию и процессуальное оформление. Проведение административного расследования должно состоять из реальных действий, направленных на получение необходимых сведений, в том числе путем проведения экспертизы, установления потерпевших, свидетелей, допроса лиц, проживающих в другой местности.\nНе являются административным расследованием процессуальные действия, совершенные в соответствии с нормами Уголовно-процессуального кодекса Российской Федерации в рамках предварительного расследования по уголовному делу, возбужденному в отношении лица, привлекаемого к административной ответственности, и впоследствии прекращенному.\nУстановив, что административное расследование фактически не проводилось, судье районного суда при подготовке дела к рассмотрению следует решить вопрос о его передаче мировому судье на основании пункта 5 части 1 статьи 29.4 КоАП РФ. В случае проведения административного расследования по делу об административном правонарушении в отраслях законодательства, не указанных в части 1 статьи 28.7 КоАП РФ, судья выносит определение о передаче дела на рассмотрение мировому судье на основании пункта 5 части 1 статьи 29.4 КоАП РФ;\nб) судьи гарнизонных военных судов рассматривают дела обо всех правонарушениях, предусмотренных частями 1 и 2 статьи 23.1 КоАП РФ, если они совершены военнослужащими и гражданами, призванными на военные сборы (абзац первый части 3 статьи 23.1 КоАП РФ);\nв) судьи рассматривают также отнесенные к компетенции иных органов (должностных лиц) дела, указанные в части 2 статьи 23.1 КоАП РФ, при условии, что они были переданы на их рассмотрение в связи с тем, что уполномоченный орган (должностное лицо) с учетом характера совершенного правонарушения, личности лица, в отношении которого ведется производство по делу об административном правонарушении, и других указанных в законе обстоятельств признал необходимым обсудить вопрос о возможности применения мер наказания, назначение которых отнесено к исключительной компетенции судей.\nУчитывая, что передача дел данной категории на рассмотрение судье относится к компетенции названных выше органов (должностных лиц), судья в указанном случае обязан принять дело к рассмотрению по существу;\nг) по общему правилу дела об административных правонарушениях, предусмотренных КоАП РФ, подведомственные судьям судов общей юрисдикции, рассматривают мировые судьи. Подсудность дел мировым судьям определяется путем исключения категорий дел, отнесенных к компетенции судей районных судов, военных судов и арбитражных судов;\nд) судьи судов общей юрисдикции не вправе рассматривать дела об административных правонарушениях, перечисленных в абзаце четвертом части 3 статьи 23.1 КоАП РФ, совершенных юридическими лицами, а также индивидуальными предпринимателями, поскольку эти дела подсудны судьям арбитражных судов. Указанный в этой норме перечень видов правонарушений является исчерпывающим и не подлежит расширительному толкованию. Дела, указанные в абзаце четвертом части 3 статьи 23.1 КоАП РФ, не подсудны судьям судов общей юрисдикции и в том случае, когда по ним в соответствии со статьей 28.7 КоАП РФ проводилось административное расследование, а также когда индивидуальный предприниматель, совершивший административное правонарушение из числа названных в абзаце четвертом части 3 статьи 23.1 КоАП РФ, утратил статус индивидуального предпринимателя. Дела об административных правонарушениях, перечисленных в абзаце пятом части 3 статьи 23.1 КоАП РФ, подсудны судьям арбитражных судов независимо от того, кем было совершено административное правонарушение: должностным лицом, юридическим лицом или индивидуальным предпринимателем.\nе) дела об иных правонарушениях, отнесенных к компетенции судей (части 1 и 2 статьи 23.1 КоАП РФ) и не указанных в абзацах четвертом и пятом части 3 статьи 23.1 КоАП РФ, подсудны судьям судов общей юрисдикции независимо от характера административного правонарушения и статуса лица, привлекаемого к ответственности (в том числе дела о правонарушениях, совершенных юридическими лицами, а также гражданами, являющимися индивидуальными предпринимателями);\nж) в соответствии со статьей 23.2 КоАП РФ рассмотрение дел об административных правонарушениях, совершенных лицами от шестнадцати до восемнадцати лет (в том числе дела, перечисленные в частях 1 и 2 статьи 23.1 КоАП РФ), отнесено к компетенции комиссий по делам несовершеннолетних и защите их прав, за исключением дел об административных правонарушениях, предусмотренных статьей 11.18 КоАП РФ, и дел о правонарушениях в области дорожного движения, которые рассматриваются комиссией в случае передачи дела на ее рассмотрение уполномоченным органом (должностным лицом). Указанными комиссиями рассматриваются также дела о правонарушениях, предусмотренных статьями 5.35, 5.36, 6.10, 20.22 КоАП РФ.\nПоскольку комиссия по делам несовершеннолетних и защите их прав не может назначать виды наказания, отнесенные к исключительной компетенции судей, дело об административном правонарушении, предусмотренном статьей, указанной в части 2 статьи 23.1 КоАП РФ, которое совершено несовершеннолетним, может быть передано указанной комиссией на рассмотрение судьи (пункт 1 части 2 статьи 29.9 КоАП РФ);\nз) при определении подсудности необходимо также учитывать закрепленные в статье 29.5 КоАП РФ правила о территориальной подсудности дел об административных правонарушениях.\nВ части первой этой статьи закреплено общее правило, в соответствии с которым дело рассматривается по месту совершения правонарушения. Местом совершения административного правонарушения является место совершения противоправного действия независимо от места наступления его последствий, а если такое деяние носит длящийся характер, - место окончания противоправной деятельности, ее пресечения; если правонарушение совершено в форме бездействия, то местом его совершения следует считать место, где должно было быть совершено действие, выполнена возложенная на лицо обязанность.\nПри определении территориальной подсудности дел об административных правонарушениях, объективная сторона которых выражается в бездействии в виде неисполнения установленной правовым актом обязанности, необходимо исходить из места жительства физического лица, в том числе индивидуального предпринимателя, места исполнения должностным лицом своих обязанностей либо места нахождения юридического лица, определяемого в соответствии со статьей 54 ГК РФ. Вместе с тем подсудность дел об административных правонарушениях, возбужденных в отношении юридических лиц по результатам проверки их филиалов, определяется местом нахождения филиалов, в деятельности которых соответствующие нарушения были выявлены и должны быть устранены.\nОбщая территориальная подсудность в соответствии с частью 1 статьи 29.5 КоАП РФ может быть изменена по ходатайству лица, в отношении которого ведется производство по делу об административном правонарушении, о передаче дела для рассмотрения по месту жительства данного лица. При этом необходимо учитывать, что КоАП РФ не предусматривает возможность передачи дела для рассмотрения по месту нахождения юридического лица в случае поступления такого ходатайства от его законного представителя (защитника).\nРазрешая ходатайство лица, в отношении которого ведется производство по делу об административном правонарушении, о рассмотрении дела по месту его жительства, необходимо иметь в виду, что КоАП РФ не обязывает данное лицо указывать причины, по которым оно просит об этом, и представлять доказательства, подтверждающие уважительность таких причин.\nСудья вправе отказать в удовлетворении ходатайства указанного лица с учетом конкретных обстоятельств дела, если это необходимо для обеспечения баланса прав всех участников производства по делу об административном правонарушении или защиты публичных интересов.\nК таким случаям, в частности, относятся:\nвозражение потерпевшего, обладающего процессуальными правами, аналогичными правам лица, в отношении которого ведется производство по делу об административном правонарушении, привлечение которого к участию в деле является обязательным (части 2 и 3 статьи 25.2 КоАП РФ). Удовлетворение ходатайства лица, в отношении которого ведется производство по делу об административном правонарушении, о рассмотрении дела по месту его жительства в данном случае может повлечь нарушение права потерпевшего на судебную защиту;\nустановление фактов недобросовестного пользования своими процессуальными правами лицом, в отношении которого ведется производство по делу об административном правонарушении, выражающегося, например, в последовательном заявлении ходатайств об отложении рассмотрения дела об административном правонарушении по различным основаниям, а впоследствии - о рассмотрении дела об административном правонарушении по месту жительства;\nвозбуждение в отношении лица дела об административном правонарушении, санкция за совершение которого предусматривает назначение наказания в виде административного ареста или административного выдворения, поскольку из положений части 3 статьи 25.1, части 4 статьи 29.6 КоАП РФ следует, что такие дела должны рассматриваться в день получения протокола об административном правонарушении и с обязательным присутствием лица, в отношении которого ведется производство по делу об административном правонарушении.\nВ определении об отказе в удовлетворении названного выше ходатайства должны быть приведены основания, которые препятствуют рассмотрению дела по месту жительства лица, в отношении которого ведется производство по делу об административном правонарушении.\nПо делам, перечисленным в частях 1.1, 2, 3, 5 и 6 статьи 29.5 КоАП РФ, установлена исключительная территориальная подсудность, не подлежащая изменению по ходатайству лица, в отношении которого ведется производство по делу. При наличии совокупности установленных частями 1.1, 2, 3 и 6 статьи 29.5 КоАП РФ критериев по одному делу об административном правонарушении судье необходимо установить приоритет между этими нормами (например, если по делу об административном правонарушении, совершенном несовершеннолетним, было проведено административное расследование, нормой, определяющей территориальную подсудность, следует считать часть 3 статьи 29.5 КоАП РФ).\nЕсли при подготовке дела к рассмотрению судьей будет установлено, что рассмотрение данного дела не относится к его компетенции, он должен вынести определение о передаче протокола об административном правонарушении и других материалов на рассмотрение по подведомственности на основании пункта 5 части 1 статьи 29.4 КоАП РФ. Если рассмотрение дела относится к компетенции судьи арбитражного суда, то судья выносит определение о возвращении материалов дела органу или должностному лицу, составившему протокол об административном правонарушении, который вправе обратиться в арбитражный суд с заявлением о привлечении лица к административной ответственности (часть 2 статьи 202 АПК РФ).\nПри определении территориальной подсудности дел об административных правонарушениях, по которым административное расследование проводилось должностным лицом структурного подразделения территориального органа федерального органа исполнительной власти (например, межрайонного отдела, межрайонного отделения, отдела, отделения, территориального пункта), необходимо учитывать, что исходя из положений части 2 статьи 29.5 КоАП РФ дело в указанном случае подлежит рассмотрению судьей районного суда по месту нахождения названного структурного подразделения, проводившего административное расследование."],
["4","В порядке подготовки дела к рассмотрению судья должен также установить, правильно ли составлен протокол об административном правонарушении с точки…","","","4. В порядке подготовки дела к рассмотрению судья должен также установить, правильно ли составлен протокол об административном правонарушении с точки зрения полноты исследования события правонарушения и сведений о лице, его совершившем, а также соблюдения процедуры оформления протокола.\nСущественным недостатком протокола является отсутствие данных, прямо перечисленных в части 2 статьи 28.2 КоАП РФ, и иных сведений в зависимости от их значимости для данного конкретного дела об административном правонарушении (например, отсутствие данных о том, владеет ли лицо, в отношении которого возбуждено дело об административном правонарушении, языком, на котором ведется производство по делу, а также данных о предоставлении переводчика при составлении протокола и т.п.).\nНесущественными являются такие недостатки протокола, которые могут быть восполнены при рассмотрении дела по существу, а также нарушение установленных статьями 28.5 и 28.8 КоАП РФ сроков составления протокола об административном правонарушении и направления протокола для рассмотрения судье, поскольку эти сроки не являются пресекательными, либо составление протокола в отсутствие лица, в отношении которого возбуждено дело об административном правонарушении, если этому лицу было надлежащим образом сообщено о времени и месте его составления, но оно не явилось в назначенный срок и не уведомило о причинах неявки или причины неявки были признаны неуважительными.\nВ том случае, когда протокол об административном правонарушении составлен неправомочным лицом либо когда протокол или другие материалы оформлены неправильно, материалы представлены неполно, судье на основании пункта 4 части 1 статьи 29.4 КоАП РФ необходимо вынести определение о возвращении протокола об административном правонарушении и других материалов дела в орган или должностному лицу, которыми составлен протокол. Определение судьи должно быть мотивированным, содержать указание на выявленные недостатки протокола и других материалов, требующие устранения.\nВозвращение протокола возможно только при подготовке дела к судебному рассмотрению и не допускается при рассмотрении дела об административном правонарушении по существу, поскольку часть 2 статьи 29.9 КоАП РФ не предусматривает возможности вынесения определения о возвращении протокола и иных материалов органу или должностному лицу, составившим протокол, по результатам рассмотрения дела.\nВ связи с тем, что определение о возвращении протокола об административном правонарушении исключает возможность дальнейшего движения дела, оно может быть обжаловано лицом, в отношении которого ведется производство по делу об административном правонарушении, потерпевшим, поскольку затрагивает право указанных лиц на судебную защиту, а также опротестовано прокурором. Вместе с тем КоАП РФ не предусматривает возможность обжалования такого определения должностным лицом, составившим протокол об административном правонарушении.\nПри этом необходимо иметь в виду, что передача на рассмотрение судье дел об административных правонарушениях, перечисленных в части 2 статьи 23.1 КоАП РФ, осуществляется на основании вынесенного в соответствии с пунктом 5 части 1 статьи 29.4 КоАП РФ определения органа или должностного лица, к которым поступило такое дело. Указанное определение должно отвечать требованиям статьи 29.12 КоАП РФ, в том числе содержать мотивы принятого решения. Вместе с тем отсутствие приведенных мотивов в определении о передаче дела на рассмотрение судье не может являться основанием для возвращения протокола и других материалов дела в орган или должностному лицу, которыми составлен протокол.\nВ случае, когда при подготовке дела к судебному разбирательству будет установлено, что в материалах одного дела об административном правонарушении, переданного на рассмотрение судье, имеется несколько протоколов об административных правонарушениях, совершенных одним и тем же лицом, каждый протокол надлежит принимать для рассмотрения в отдельном производстве с вынесением постановления по каждому совершенному правонарушению в соответствии с частью 1 статьи 4.4 КоАП РФ.\nЕсли из протоколов об административных правонарушениях усматривается наличие оснований для назначения административного наказания по правилам части 2 статьи 4.4 КоАП РФ, то следует вынести определение об объединении таких материалов и рассмотреть их в одном производстве с вынесением одного постановления."],
["5","Проверяя полномочия должностного лица на составление протокола, следует учитывать положения, содержащиеся в статье 28.3 КоАП РФ, а также нормативные…","","","5. Проверяя полномочия должностного лица на составление протокола, следует учитывать положения, содержащиеся в статье 28.3 КоАП РФ, а также нормативные акты соответствующих федеральных органов исполнительной власти (часть 4 статьи 28.3 КоАП РФ).\nВ случае реорганизации федеральных органов исполнительной власти необходимо проверять, сохранено ли за соответствующими должностными лицами этих органов право на составление протокола и рассмотрение дела об административном правонарушении и не переданы ли эти функции должностным лицам других федеральных органов исполнительной власти.\nВ случае упразднения указанных в главе 23 КоАП РФ или в законе субъекта Российской Федерации органа, учреждения, их структурных подразделений, должностными лицами которых был составлен протокол, либо упразднения должности должностного лица до внесения соответствующих изменений и дополнений в КоАП РФ или в закон субъекта Российской Федерации подведомственные им дела об административных правонарушениях рассматриваются судьями (часть 1 статьи 22.3 КоАП РФ)."],
["6","В целях соблюдения установленных статьей 29.6 КоАП РФ сроков рассмотрения дел об административных правонарушениях судье необходимо принимать меры для…","","","6. В целях соблюдения установленных статьей 29.6 КоАП РФ сроков рассмотрения дел об административных правонарушениях судье необходимо принимать меры для быстрого извещения участвующих в деле лиц о времени и месте судебного рассмотрения. Поскольку КоАП РФ не содержит каких-либо ограничений, связанных с таким извещением, оно в зависимости от конкретных обстоятельств дела может быть произведено с использованием любых доступных средств связи, позволяющих контролировать получение информации лицом, которому оно направлено (судебной повесткой, телеграммой, телефонограммой, факсимильной связью и т.п., посредством СМС-сообщения, в случае согласия лица на уведомление таким способом и при фиксации факта отправки и доставки СМС-извещения адресату).\nЛицо, в отношении которого ведется производство по делу, считается извещенным о времени и месте судебного рассмотрения и в случае, когда из указанного им места жительства (регистрации) поступило сообщение об отсутствии адресата по указанному адресу, о том, что лицо фактически не проживает по этому адресу либо отказалось от получения почтового отправления, а также в случае возвращения почтового отправления с отметкой об истечении срока хранения, если были соблюдены положения Особых условий приема, вручения, хранения и возврата почтовых отправлений разряда \"Судебное\", утвержденных приказом ФГУП \"Почта России\" от 31 августа 2005 года N 343."],
["7","В соответствии с частью 2 статьи 25.11 КоАП РФ прокурор должен быть извещен о времени и месте рассмотрения каждого дела об административном…","","","7. В соответствии с частью 2 статьи 25.11 КоАП РФ прокурор должен быть извещен о времени и месте рассмотрения каждого дела об административном правонарушении, совершенном несовершеннолетним, а также дела об административном правонарушении, возбужденного по инициативе прокурора."],
["8","Если лицо, в отношении которого возбуждено дело об административном правонарушении, изъявит желание иметь для оказания юридической помощи защитника,…","","","8. Если лицо, в отношении которого возбуждено дело об административном правонарушении, изъявит желание иметь для оказания юридической помощи защитника, то адвокат или иное лицо, приглашенное им для осуществления защиты при рассмотрении дела, должны быть допущены к участию в деле при условии соблюдения требований, перечисленных в части 3 статьи 25.5 КоАП РФ.\nПри применении части 3 статьи 25.5 КоАП РФ необходимо учитывать, что, поскольку КоАП РФ не регулирует вопрос о том, каким образом должны быть оформлены полномочия защитника и представителя на участие в деле об административном правонарушении, данный вопрос должен быть решен применительно к общим положениям частей 2 и 3 статьи 53 ГПК РФ, в которых закреплен порядок оформления полномочий представителя.\nЕсли лицо, привлекаемое к административной ответственности, либо потерпевший в соответствии с частью 2 статьи 24.4 КоАП РФ в судебном заседании заявит ходатайство о привлечении защитника или представителя к участию в деле об административном правонарушении, то такой защитник или представитель должен быть допущен к участию в деле об административном правонарушении без представления соответствующей доверенности.\nПри этом право представителя на подписание и подачу жалоб на постановление по делу об административном правонарушении, на решение по жалобе на постановление по делу об административном правонарушении, на отказ от таких жалоб, на получение взысканных расходов, понесенных в связи с рассмотрением дела об административном правонарушении, на получение изъятых и возвращаемых орудий совершения и (или) предметов административного правонарушения должно быть специально оговорено в доверенности."],
["9","В соответствии со статьей 29.8 КоАП РФ при рассмотрении дела об административном правонарушении коллегиальным органом ведется протокол, в котором…","","","9. В соответствии со статьей 29.8 КоАП РФ при рассмотрении дела об административном правонарушении коллегиальным органом ведется протокол, в котором закрепляются проведенные процессуальные действия, объяснения, показания и заключения участвующих в деле лиц и указываются исследованные документы.\nУчитывая, что КоАП РФ не содержит запрета на ведение протокола при рассмотрении дела судьей, в необходимых случаях возможность ведения такого протокола не исключается.\nЛицо, в отношении которого ведется производство по делу об административном правонарушении, вправе заявить ходатайство о ведении протокола, которое подлежит обязательному рассмотрению на основании части 1 статьи 24.4 КоАП РФ. Отказ в удовлетворении такого ходатайства в силу части 2 статьи 24.4 и статьи 29.12 КоАП РФ оформляется мотивированным определением.\nУчастники производства по делу об административном правонарушении вправе знакомиться с протоколом судебного заседания (в случае его ведения). При несогласии с содержанием протокола указанные лица вправе изложить свои замечания в жалобе на принятое по делу постановление."],
["10","Поскольку должностные лица, составившие протокол об административном правонарушении, а также органы и должностные лица, вынесшие постановление по…","","","10. Поскольку должностные лица, составившие протокол об административном правонарушении, а также органы и должностные лица, вынесшие постановление по делу об административном правонарушении, не являются участниками производства по делам об административных правонарушениях, круг которых перечислен в главе 25 КоАП РФ, они не вправе заявлять ходатайства, отводы. Вместе с тем при рассмотрении дел о привлечении лиц к ответственности за административное правонарушение, а также по жалобам и протестам на постановления по делам об административных правонарушениях в случае необходимости не исключается возможность вызова в суд указанных лиц для выяснения возникших вопросов.\nЧастью 1.1 статьи 30.1 КоАП РФ должностным лицам, уполномоченным в соответствии со статьей 28.3 КоАП РФ составлять протокол об административном правонарушении, предоставлено право обжаловать вынесенное судьей постановление по делу об административном правонарушении в вышестоящий суд. К таким лицам относится любое должностное лицо органа, выявившего правонарушение, и уполномоченное в соответствии со статьей 28.3 КоАП РФ составлять протоколы о данных административных правонарушениях (как непосредственно составившее этот протокол, так и его не составлявшее). Однако названные должностные лица не обладают правом на обжалование указанного постановления в порядке надзора (статья 30.12 КоАП РФ).\nДолжностное лицо, вынесшее постановление по делу об административном правонарушении, вправе обжаловать в вышестоящий суд решение судьи по жалобе на это постановление, в том числе в порядке надзора (часть 5 статьи 30.9, часть 4 статьи 30.12 КоАП РФ).\nСледует также иметь в виду, что часть 5 статьи 30.9 КоАП РФ не наделяет полномочиями по обжалованию решения суда по жалобе на постановление по делу об административном правонарушении, вынесенному коллегиальным органом, должностных лиц этого органа."],
["11","В соответствии с частью 1 статьи 25.2 КоАП РФ потерпевшим признается лицо, которому административным правонарушением причинен физический,…","","","11. В соответствии с частью 1 статьи 25.2 КоАП РФ потерпевшим признается лицо, которому административным правонарушением причинен физический, имущественный или моральный вред.\nИсходя из части 3 статьи 25.2 КоАП РФ право потерпевшего на участие в деле об административном правонарушении должно быть обеспечено независимо от того, является ли наступление последствий признаком состава административного правонарушения."],
["12","В случаях, когда при производстве по делу об административном правонарушении возникает необходимость в использовании специальных познаний в науке,…","","","12. В случаях, когда при производстве по делу об административном правонарушении возникает необходимость в использовании специальных познаний в науке, технике, искусстве или ремесле, судья на основании статьи 26.4 КоАП РФ выносит определение о назначении экспертизы. Такое определение может быть вынесено как по инициативе судьи, так и на основании ходатайства лица, в отношении которого ведется производство по делу, потерпевшего, прокурора, защитника.\nВ определении о назначении экспертизы эксперту должны быть разъяснены его права и обязанности, он также должен быть предупрежден об административной ответственности за дачу заведомо ложного заключения (статья 17.9 КоАП РФ).\nПри решении вопроса о назначении экспертизы по делу об административном правонарушении с учетом объема и содержания прав, предоставленных потерпевшему и лицу, в отношении которого ведется производство по делу (часть 1 статьи 25.1, часть 2 статьи 25.2, часть 4 статьи 26.4 КоАП РФ), необходимо выяснить у названных участников производства по делу их мнение о кандидатуре эксперта, экспертного учреждения и о вопросах, которые должны быть разрешены экспертом.\nПоскольку статьей 25.9 КоАП РФ эксперту не предоставлено право истребовать доказательства для производства экспертизы и выяснять у участников производства какие-либо обстоятельства, все необходимые для производства экспертизы данные должны быть установлены и собраны судьей, назначившим экспертизу, и предоставлены эксперту."],
["13","При рассмотрении дел об административных правонарушениях, а также по жалобам на постановления или решения по делам об административных…","","","13. При рассмотрении дел об административных правонарушениях, а также по жалобам на постановления или решения по делам об административных правонарушениях судья должен исходить из закрепленного в статье 1.5 КоАП РФ принципа административной ответственности - презумпции невиновности лица, в отношении которого осуществляется производство по делу. Реализация этого принципа заключается в том, что лицо, привлекаемое к административной ответственности, не обязано доказывать свою невиновность, вина в совершении административного правонарушения устанавливается судьями, органами, должностными лицами, уполномоченными рассматривать дела об административных правонарушениях. Неустранимые сомнения в виновности лица, привлекаемого к административной ответственности, должны толковаться в пользу этого лица."],
["13.1","Согласно пункту 6 части 1 статьи 24.5 КоАП РФ производство по делу об административном правонарушении не может быть начато, а начатое подлежит…","","","13.1. Согласно пункту 6 части 1 статьи 24.5 КоАП РФ производство по делу об административном правонарушении не может быть начато, а начатое подлежит прекращению в случае истечения установленных статьей 4.5 КоАП РФ сроков давности привлечения к административной ответственности. В постановлении о прекращении производства по делу по названному основанию, исходя из положения, закрепленного в пункте 4 части 1 статьи 29.10 КоАП РФ, должны быть указаны все установленные по делу обстоятельства, а не только связанные с истечением срока давности привлечения к административной ответственности.\nСледует иметь в виду, что в случае, когда постановление о прекращении производства по делу в связи с истечением срока давности привлечения к административной ответственности либо решение по результатам рассмотрения жалобы на это постановление обжалуется лицом, в отношении которого составлялся протокол об административном правонарушении, настаивающим на своей невиновности, то ему не может быть отказано в проверке и оценке доводов об отсутствии в его действиях (бездействии) состава административного правонарушения в целях обеспечения судебной защиты прав и свобод этого лица (часть 3 статьи 30.6, часть 3 статьи 30.9 КоАП РФ).\nУстановив при рассмотрении жалобы такого лица обоснованность выводов юрисдикционного органа, а также правильность исчисления срока давности привлечения к административной ответственности в зависимости от категории дела, судья отказывает в ее удовлетворении и оставляет постановление без изменения. При этом необходимо учитывать, что в названном постановлении о прекращении производства по делу не могут содержаться выводы юрисдикционного органа о виновности лица, в отношении которого был составлен протокол об административном правонарушении. При наличии таких выводов в обжалуемом постановлении судья, с учетом положений статьи 1.5 КоАП РФ о презумпции невиновности, обязан вынести решение об изменении постановления, исключив из него указание на вину этого лица (пункт 2 части 1 статьи 30.7 КоАП РФ).\nЕсли при рассмотрении жалобы будет установлено, что в действиях лица, в отношении которого составлен протокол об административном правонарушении, не содержится состава административного правонарушения либо отсутствовало само событие административного правонарушения, то такое постановление подлежит отмене с вынесением решения о прекращении производства по делу в соответствии с пунктом 1 либо пунктом 2 статьи 24.5 КоАП РФ."],
["14","Абзац исключен","","","14. Абзац исключен. - Постановление Пленума Верховного Суда РФ от 10.06.2010 N 13.\nСрок давности привлечения к ответственности исчисляется по общим правилам исчисления сроков - со дня, следующего за днем совершения административного правонарушения (за днем обнаружения правонарушения). В случае совершения административного правонарушения, выразившегося в форме бездействия, срок привлечения к административной ответственности исчисляется со дня, следующего за последним днем периода, предоставленного для исполнения соответствующей обязанности.\nСогласно части 2 статьи 4.5 КоАП РФ при длящемся административном правонарушении сроки, предусмотренные частью первой этой статьи, начинают исчисляться со дня обнаружения административного правонарушения. При применении данной нормы судьям необходимо исходить из того, что длящимся является такое административное правонарушение (действие или бездействие), которое выражается в длительном непрекращающемся невыполнении или ненадлежащем выполнении предусмотренных законом обязанностей. При этом следует учитывать, что такие обязанности могут быть возложены и иным нормативным правовым актом, а также правовым актом ненормативного характера, например представлением прокурора, предписанием органа (должностного лица), осуществляющего государственный надзор (контроль). Невыполнение предусмотренной названными правовыми актами обязанности к установленному сроку свидетельствует о том, что административное правонарушение не является длящимся. При этом необходимо иметь в виду, что днем обнаружения длящегося административного правонарушения считается день, когда должностное лицо, уполномоченное составлять протокол об административном правонарушении, выявило факт его совершения.\nСрок давности привлечения к административной ответственности за правонарушение, в отношении которого предусмотренная правовым актом обязанность не была выполнена к определенному сроку, начинает течь с момента наступления указанного срока.\nПроверяя соблюдение срока давности привлечения к административной ответственности, необходимо учитывать, что КоАП РФ предусматривает единственный случай приостановления течения этого срока. Таким случаем является удовлетворение ходатайства лица, в отношении которого ведется производство по делу об административном правонарушении, о рассмотрении дела по месту его жительства, когда время пересылки дела не включается в срок давности привлечения к административной ответственности. В силу части 5 статьи 4.5 КоАП РФ течение названного срока приостанавливается с момента удовлетворения данного ходатайства до момента поступления материалов дела судье, в орган или должностному лицу, уполномоченным рассматривать дело по месту жительства лица, в отношении которого ведется производство по делу.\nПри удовлетворении ходатайства о рассмотрении дела по месту жительства этого лица судья не должен выносить какой-либо процессуальный документ о приостановлении течения срока давности привлечения к административной ответственности, поскольку это не предусмотрено КоАП РФ.\nПроверяя соблюдение срока давности привлечения к административной ответственности, следует также учитывать, что КоАП РФ не предусматривает возможности перерыва данного срока.\nПо смыслу части 1 статьи 4.5 и пункта 3 части 1 статьи 30.7 КоАП РФ истечение сроков привлечения к административной ответственности на время пересмотра постановления не влечет за собой его отмену и прекращение производства по делу, если для этого отсутствуют иные основания."],
["15","В соответствии с частью 3 статьи 2.1 КоАП РФ в случае совершения юридическим лицом административного правонарушения и выявления конкретных…","","","15. В соответствии с частью 3 статьи 2.1 КоАП РФ в случае совершения юридическим лицом административного правонарушения и выявления конкретных должностных лиц, по вине которых оно было совершено (статья 2.4 КоАП РФ), допускается привлечение к административной ответственности по одной и той же норме как юридического лица, так и указанных должностных лиц.\nПри определении степени ответственности должностного лица за совершение административного правонарушения, которое явилось результатом выполнения решения коллегиального органа юридического лица, необходимо выяснять, предпринимались ли должностным лицом меры с целью обратить внимание коллегиального органа либо администрации на невозможность исполнения данного решения в связи с тем, что это может привести к совершению административного правонарушения.\nПоскольку КоАП РФ не предусматривает в указанном случае каких-либо ограничений при назначении административного наказания, судья вправе применить к юридическому и должностному лицу любую меру наказания в пределах санкции соответствующей статьи, в том числе и максимальную, учитывая при этом смягчающие, отягчающие и иные обстоятельства, влияющие на степень ответственности каждого из этих лиц.\nПривлечение к уголовной ответственности должностного лица не может в силу части 3 статьи 2.1 КоАП РФ служить основанием для освобождения юридического лица от административной ответственности."],
["16","Пунктом 2 части 1 статьи 4.3 КоАП РФ в качестве обстоятельства, отягчающего административную ответственность, предусмотрено повторное совершение…","","","16. Пунктом 2 части 1 статьи 4.3 КоАП РФ в качестве обстоятельства, отягчающего административную ответственность, предусмотрено повторное совершение однородного административного правонарушения, если за совершение первого административного правонарушения лицо уже подвергалось административному наказанию, по которому не истек предусмотренный статьей 4.6 КоАП РФ срок.\nПри этом необходимо иметь в виду, что однородным считается правонарушение, имеющее единый родовой объект посягательства, независимо от того, установлена ли административная ответственность за совершенные правонарушения в одной или нескольких статьях КоАП РФ (например, совершение лицом, считающимся подвергнутым административному наказанию за нарушение правил дорожного движения по части 2 статьи 12.9 КоАП РФ, административного правонарушения в области дорожного движения, предусмотренного частью 4 статьи 12.15 КоАП РФ)."],
["17","Утратил силу","","","17. Утратил силу. - Постановление Пленума Верховного Суда РФ от 23.12.2021 N 45."],
["18","При рассмотрении дела об административном правонарушении собранные по делу доказательства должны оцениваться в соответствии со статьей 26.11 КоАП РФ,…","","","18. При рассмотрении дела об административном правонарушении собранные по делу доказательства должны оцениваться в соответствии со статьей 26.11 КоАП РФ, а также с позиции соблюдения требований закона при их получении (часть 3 статьи 26.2 КоАП РФ).\nНарушением, влекущим невозможность использования доказательств, может быть признано, в частности, получение объяснений потерпевшего, свидетеля, лица, в отношении которого ведется производство по делу об административном правонарушении, которым не были предварительно разъяснены их права и обязанности, предусмотренные частью 1 статьи 25.1, частью 2 статьи 25.2, частью 3 статьи 25.6 КоАП РФ, статьей 51 Конституции Российской Федерации, а свидетели, специалисты, эксперты не были предупреждены об административной ответственности соответственно за дачу заведомо ложных показаний, пояснений, заключений по статье 17.9 КоАП РФ, а также существенное нарушение порядка назначения и проведения экспертизы.\nНе является нарушением порядка назначения и проведения экспертизы неисполнение обязанностей, изложенных в части 4 статьи 26.4 КоАП РФ, если лицу, в отношении которого ведется производство по делу об административном правонарушении, было надлежащим образом сообщено о времени и месте ознакомления с определением о назначении экспертизы, но оно в назначенный срок не явилось и не уведомило о причинах неявки, либо если названные лицом причины неявки были признаны неуважительными.\nПротоколы и иные материалы ранее прекращенного уголовного дела в отношении лица, привлекаемого к административной ответственности за те же действия (бездействие), могут быть использованы в качестве доказательств при рассмотрении дела об административном правонарушении."],
["19","Кодексом Российской Федерации об административных правонарушениях предусмотрена возможность привлечения к административной ответственности только за…","","","19. Кодексом Российской Федерации об административных правонарушениях предусмотрена возможность привлечения к административной ответственности только за оконченное правонарушение.\nАдминистративное правонарушение считается оконченным с момента, когда в результате действия (бездействия) правонарушителя имеются все предусмотренные законом признаки состава административного правонарушения. В случае, если в соответствии с нормативными правовыми актами обязанность должна быть выполнена к определенному сроку, правонарушение является оконченным с момента истечения этого срока."],
["20","Несмотря на обязательность указания в протоколе об административном правонарушении наряду с другими сведениями, перечисленными в части 2 статьи 28.2…","","","20. Несмотря на обязательность указания в протоколе об административном правонарушении наряду с другими сведениями, перечисленными в части 2 статьи 28.2 КоАП РФ, конкретной статьи КоАП РФ или закона субъекта Российской Федерации, предусматривающей административную ответственность за совершенное лицом правонарушение, право окончательной юридической квалификации действий (бездействия) лица КоАП РФ относит к полномочиям судьи.\nЕсли при рассмотрении дела об административном правонарушении будет установлено, что протокол об административном правонарушении содержит неправильную квалификацию совершенного правонарушения, то судья вправе переквалифицировать действия (бездействие) лица, привлекаемого к административной ответственности, на другую статью (часть статьи) КоАП РФ, предусматривающую состав правонарушения, имеющий единый родовой объект посягательства, в том числе и в случае, если рассмотрение данного дела отнесено к компетенции должностных лиц или несудебных органов, при условии, что назначаемое наказание не ухудшит положение лица, в отношении которого ведется производство по делу.\nВ таком же порядке может быть решен вопрос о переквалификации действий (бездействия) лица при пересмотре постановления или решения по делу об административном правонарушении."],
["21","При решении вопроса о назначении вида и размера административного наказания судье необходимо учитывать, что КоАП РФ допускает возможность назначения…","","","21. При решении вопроса о назначении вида и размера административного наказания судье необходимо учитывать, что КоАП РФ допускает возможность назначения административного наказания лишь в пределах санкций, установленных законом, предусматривающим ответственность за данное административное правонарушение с учетом характера совершенного правонарушения, личности виновного, имущественного положения правонарушителя - физического лица (индивидуального предпринимателя), финансового положения юридического лица, привлекаемого к административной ответственности, обстоятельств, смягчающих и отягчающих административную ответственность (статьи 4.1 - 4.5 КоАП РФ). Поэтому судья не вправе назначить наказание ниже низшего предела, установленного санкцией соответствующей статьи, либо применить наказание, не предусмотренное статьей 3.2 КоАП РФ.\nВместе с тем, если при рассмотрении дела будет установлена малозначительность совершенного административного правонарушения, судья на основании статьи 2.9 КоАП РФ вправе освободить виновное лицо от административной ответственности и ограничиться устным замечанием, о чем должно быть указано в постановлении о прекращении производства по делу. Если малозначительность административного правонарушения будет установлена при рассмотрении жалобы на постановление по делу о таком правонарушении, то на основании пункта 3 части 1 статьи 30.7 КоАП РФ выносится решение об отмене постановления и о прекращении производства по делу.\nМалозначительным административным правонарушением является действие или бездействие, хотя формально и содержащее признаки состава административного правонарушения, но с учетом характера совершенного правонарушения и роли правонарушителя, размера вреда и тяжести наступивших последствий не представляющее существенного нарушения охраняемых общественных правоотношений.\nПри этом необходимо иметь в виду, что с учетом признаков объективной стороны некоторых административных правонарушений, они ни при каких обстоятельствах не могут быть признаны малозначительными, поскольку существенно нарушают охраняемые общественные отношения. К ним, в частности, относятся административные правонарушения, предусмотренные статьями 12.8, 12.26 КоАП РФ.\nТакие обстоятельства, как, например, личность и имущественное положение привлекаемого к ответственности лица, добровольное устранение последствий правонарушения, возмещение причиненного ущерба, не являются обстоятельствами, характеризующими малозначительность правонарушения. Они в силу частей 2 и 3 статьи 4.1 КоАП РФ учитываются при назначении административного наказания."],
["22","По делам, перечисленным в части 2 статьи 23.1 КоАП РФ, переданным уполномоченным органом (должностным лицом) на рассмотрение судьи, последний не…","","","22. По делам, перечисленным в части 2 статьи 23.1 КоАП РФ, переданным уполномоченным органом (должностным лицом) на рассмотрение судьи, последний не связан мнением указанного органа (должностного лица) и вправе с учетом смягчающих и отягчающих обстоятельств, руководствуясь общими правилами назначения наказания, назначить любую меру наказания, предусмотренную санкцией соответствующей статьи КоАП РФ, в том числе и такую, применение которой не относится к исключительной компетенции судей.\nСогласно части 4 статьи 4.1 КоАП РФ назначение административного наказания не освобождает лицо от исполнения обязанности, за неисполнение которой было назначено административное наказание, поэтому при решении вопроса об изъятых вещах, не прошедших таможенного оформления, в постановлении по делу об административном правонарушении необходимо указывать на возможность их выдачи владельцу только после таможенного оформления."],
["23","При назначении наказания в виде административного ареста следует иметь в виду, что в соответствии с частью 2 статьи 3.9 КоАП РФ данный вид наказания…","","","23. При назначении наказания в виде административного ареста следует иметь в виду, что в соответствии с частью 2 статьи 3.9 КоАП РФ данный вид наказания может быть назначен лишь в исключительных случаях, когда с учетом характера деяния и личности нарушителя применение иных видов наказания не обеспечит реализации задач административной ответственности.\nПоскольку административный арест не может быть применен к лицам, перечисленным в части 2 статьи 3.9 КоАП РФ, в том числе к беременным женщинам, женщинам, имеющим детей в возрасте до четырнадцати лет, несовершеннолетним, инвалидам I и II групп, военнослужащим, судья при решении вопроса о привлечении лица к административной ответственности за правонарушение, допускающее наложение ареста, должен проверить наличие данных обстоятельств.\nЕсли лицо, в отношении которого вынесено постановление об административном аресте, отбывает этот вид административного наказания по другому делу, то исходя из части 1 статьи 32.8 КоАП РФ срок отбывания наказания по данному делу начинает течь со дня вынесения постановления об административном аресте одновременно с неотбытой частью срока административного ареста по другому делу.\nВ постановлении о назначении административного ареста судье следует указать момент, с которого подлежит исчислению срок ареста. При определении начального момента течения этого срока необходимо иметь в виду часть 4 статьи 27.5 КоАП РФ, согласно которой срок административного задержания лица исчисляется со времени доставления в соответствии со статьей 27.2 КоАП РФ, а лица, находящегося в состоянии опьянения, - со времени его вытрезвления."],
["23.1","При назначении административного наказания в виде административного выдворения иностранных граждан или лиц без гражданства за пределы территории…","","","23.1. При назначении административного наказания в виде административного выдворения иностранных граждан или лиц без гражданства за пределы территории Российской Федерации надлежит учитывать, что согласно части 4 статьи 3.10 КоАП РФ административное наказание в виде административного выдворения может быть назначено в форме принудительного выдворения за пределы территории Российской Федерации или контролируемого самостоятельного выезда из Российской Федерации. При этом указание на форму административного выдворения в постановлении по делу об административном правонарушении является обязательным.\nЕсли форма, в которой должно исполняться административное наказание в виде выдворения, не была указана в постановлении о назначении этого административного наказания, то указанный вопрос может быть разрешен судьей, вынесшим постановление об административном выдворении, на основании части 3 статьи 31.4 КоАП РФ по заявлению органа, должностного лица, приводящих постановление в исполнение, а также по заявлению лица, в отношении которого оно вынесено. Названный вопрос также может быть разрешен судьей при рассмотрении жалобы, протеста прокурора на не вступившее в законную силу постановление об административном выдворении без его отмены при условии, если из материалов дела усматривается, что судьей, вынесшим постановление, была определена форма административного выдворения, но она не отражена в постановлении (например, судьей на основании части 2 статьи 29.10 КоАП РФ иностранный гражданин (лицо без гражданства) был помещен в специальное учреждение до его выдворения).\nСледует также учитывать, что выдворение лица из страны, в которой проживают члены его семьи, может нарушать право на уважение семейной жизни.\nПоэтому при назначении наказания в виде административного выдворения за пределы Российской Федерации судья должен исходить из действительной необходимости применения к иностранному гражданину или лицу без гражданства такой меры ответственности, а также из ее соразмерности целям административного наказания, с тем чтобы обеспечить достижение справедливого баланса публичных и частных интересов в рамках производства по делу об административном правонарушении.\nПри этом конкретные обстоятельства, связанные с совершением административного правонарушения (длительность незаконного нахождения на территории Российской Федерации, повторное или неоднократное привлечение к административной ответственности и т.д.), подлежат оценке в соответствии с общими правилами назначения административного наказания, основанными на принципах справедливости, соразмерности и индивидуализации ответственности.\nЕсли необходимость применения к иностранному гражданину или лицу без гражданства административного выдворения за пределы Российской Федерации как единственно возможного способа достижения целей административного наказания, связанного с предупреждением совершения новых правонарушений как самим правонарушителем, так и другими лицами (часть 1 статьи 3.1 КоАП РФ), будет установлена, назначение ему дополнительного административного наказания в виде административного выдворения не исключается."],
["23.2","В соответствии со статьями 3.2 и 3.7 КоАП РФ конфискация орудия совершения или предмета административного правонарушения является видом…","","","23.2. В соответствии со статьями 3.2 и 3.7 КоАП РФ конфискация орудия совершения или предмета административного правонарушения является видом административного наказания и может быть применена судьей при принятии решения о привлечении лица к административной ответственности и назначении административного наказания только в случае, если этот вид административного наказания предусмотрен санкцией соответствующей статьи (частью статьи) Особенной части КоАП РФ.\nПри применении административного наказания в виде конфискации орудия совершения или предмета административного правонарушения надлежит учитывать положения части 4 статьи 3.7 КоАП РФ, в соответствии с которыми конфискация орудия совершения или предмета административного правонарушения, принадлежащих на праве собственности лицу, не привлеченному к административной ответственности за данное административное правонарушение и не признанному в судебном порядке виновным в его совершении, не применяется, за исключением административных правонарушений в области таможенного дела (нарушения таможенных правил), предусмотренных главой 16 КоАП РФ.\nПри этом необходимо учитывать, что изъятие орудия совершения или предмета административного правонарушения в случае, когда это имущество в соответствии с законом изъято из оборота либо находится в противоправном владении лица по иным причинам и на этом основании подлежит обращению в собственность государства или уничтожению, не является конфискацией, то есть видом административного наказания, и предполагает лишение лица имущества, только если последний владеет им незаконно, а также не находится в прямой зависимости от факта привлечения к административной ответственности.\nИзъятие орудия совершения или предмета административного правонарушения в соответствии с частью 3 статьи 3.7 КоАП РФ у лиц, которые владеют данным имуществом на законных основаниях (например, в силу договора аренды), лишь на том основании, что оно используется с нарушением установленных законом требований, недопустимо. Исключением из этого правила являются случаи, прямо предусмотренные законом (например, пунктом 1 статьи 25 Федерального закона от 22 ноября 1995 года N 171-ФЗ \"О государственном регулировании производства и оборота этилового спирта, алкогольной и спиртосодержащей продукции\")."],
["23.3","Наказание в виде административного приостановления деятельности индивидуального предпринимателя или юридического лица может быть назначено судьей…","","","23.3. Наказание в виде административного приостановления деятельности индивидуального предпринимателя или юридического лица может быть назначено судьей районного суда лишь в случаях, предусмотренных статьями Особенной части КоАП РФ, если менее строгий вид наказания не сможет обеспечить достижение цели административного наказания, что должно быть мотивировано в постановлении по делу об административном правонарушении (абзац второй части 1 статьи 3.12, пункт 6 части 1 статьи 29.10 КоАП РФ). При назначении этого наказания надлежит учитывать характер деятельности индивидуального предпринимателя или юридического лица, характер совершенных ими действий (бездействия), а также другие обстоятельства, влияющие на создание условий для реальной возможности наступления негативных последствий для жизни или здоровья людей, возникновения эпидемии, эпизоотии, заражения (засорения) подкарантинных объектов карантинными объектами, наступления радиационной аварии или техногенной катастрофы, причинения существенного вреда состоянию или качеству окружающей среды (абзац первый части 1 статьи 3.12 КоАП РФ). Обстоятельства, создающие, по мнению судьи, угрозу причинения вреда, должны быть указаны им в постановлении по делу об административном правонарушении.\nОпределяя срок административного приостановления деятельности, необходимо иметь в виду, что он не может превышать девяноста суток, включая срок временного запрета деятельности индивидуального предпринимателя или юридического лица, если такая мера обеспечения производства по делу об административном правонарушении применялась (часть 2 статьи 3.12, часть 5 статьи 29.6 КоАП РФ). В случае применения названной меры судье следует отразить это обстоятельство в постановлении по делу, включая время фактического прекращения деятельности, указанное в протоколе о временном запрете деятельности (часть 3 статьи 27.16 КоАП РФ). Время начала и окончания срока административного приостановления деятельности индивидуального предпринимателя или юридического лица не должно определяться в постановлении, так как это не предусмотрено КоАП РФ.\nВ постановлении по делу судья обязан решить вопрос о мероприятиях, необходимых для обеспечения его исполнения, которые в зависимости от обстоятельств каждого дела могут заключаться во временном прекращении эксплуатации тех агрегатов, объектов, зданий или сооружений, принадлежащих индивидуальному предпринимателю или юридическому лицу, либо во временном прекращении осуществления индивидуальным предпринимателем или юридическим лицом, его филиалами, представительствами, структурными подразделениями, производственными участками тех видов деятельности (работ), оказания услуг, от которых исходит угроза причинения вреда охраняемым общественным отношениям (абзац второй части 2 статьи 29.10 КоАП РФ).\nВместе с тем в постановлении не должны указываться конкретные меры, направленные на исполнение названных в нем мероприятий (например, наложение пломб, опечатывание помещений, мест хранения товаров и иных материальных ценностей, отселение граждан из жилых зданий либо их перевод в другие стационарные лечебные, социальные учреждения в случае запрета эксплуатации зданий), поскольку в соответствии с частями 1 и 2 статьи 32.12 КоАП РФ и частью 2 статьи 109 Федерального закона от 2 октября 2007 г. N 229-ФЗ \"Об исполнительном производстве\" меры по обеспечению исполнения указанных в постановлении мероприятий применяются судебными приставами-исполнителями и выбираются ими самостоятельно. При этом необходимо учитывать, что часть 2 статьи 29.10 КоАП РФ предусматривает единственный случай, когда при назначении такого вида административного наказания за нарушение законодательства Российской Федерации о противодействии легализации (отмыванию) доходов, полученных преступным путем, и финансированию терроризма судья обязан одновременно с приостановлением деятельности индивидуальных предпринимателей или юридических лиц решить вопрос о мерах, необходимых для приостановления операций по счетам."],
["23.4","Следует иметь в виду, что дела об административных правонарушениях, влекущих наказание в виде административного ареста, административного выдворения…","","","23.4. Следует иметь в виду, что дела об административных правонарушениях, влекущих наказание в виде административного ареста, административного выдворения за пределы Российской Федерации иностранного гражданина или лица без гражданства либо обязательных работ, согласно части 3 статьи 25.1 КоАП РФ должны рассматриваться в присутствии лица, в отношении которого ведется производство по такому делу."],
["24","В случае совершения лицом двух и более административных правонарушений за каждое из них в силу части 1 статьи 4.4 КоАП РФ назначается наказание,…","","","24. В случае совершения лицом двух и более административных правонарушений за каждое из них в силу части 1 статьи 4.4 КоАП РФ назначается наказание, предусмотренное санкцией соответствующей статьи КоАП РФ или закона субъекта Российской Федерации, даже если дела об этих правонарушениях рассматриваются судьей одновременно.\nЕсли лицом совершено одно действие (бездействие), содержащее составы административных правонарушений, ответственность за которые предусмотрена двумя и более статьями (частями статей) КоАП РФ и рассмотрение дел о которых подведомственно одному и тому же судье, административное наказание назначается в пределах санкции, предусматривающей более строгое административное наказание в соответствии с частями 3 и 4 статьи 4.4 КоАП РФ."],
["25","При определении наказания за административное правонарушение необходимо учитывать положения части 3 статьи 3.3 КоАП РФ о допустимом сочетании видов…","","","25. При определении наказания за административное правонарушение необходимо учитывать положения части 3 статьи 3.3 КоАП РФ о допустимом сочетании видов административных наказаний за административное правонарушение, имея в виду, что за конкретное правонарушение может быть назначено только основное либо основное и одно из дополнительных наказаний, предусмотренных санкцией применяемой статьи Особенной части КоАП РФ или закона субъекта Российской Федерации. Исходя из этого в качестве основного может назначаться только одно из основных наказаний, указанных в санкции статьи, а дополнительное административное наказание не может назначаться самостоятельно.\nКроме того, при применении указанных норм необходимо иметь в виду, что, если санкция статьи КоАП РФ предусматривает обязательное назначение дополнительного административного наказания наряду с основным, но при этом дополнительное наказание не может быть назначено лицу, в отношении которого ведется производство по делу об административном правонарушении, судья вправе назначить лишь основное наказание."],
["26","При вынесении постановления о назначении административного наказания либо о прекращении производства по делу об административном правонарушении судье…","","","26. При вынесении постановления о назначении административного наказания либо о прекращении производства по делу об административном правонарушении судье следует иметь в виду, что в соответствии с частью 4 статьи 24.7 КоАП РФ в постановлении должно быть отражено принятое решение об издержках по делу.\nПри этом необходимо учитывать, что физические лица освобождены от издержек по делам об административных правонарушениях, перечень которых содержится в части 1 статьи 24.7 КоАП РФ и не подлежит расширительному толкованию.\nРазмер издержек по делу об административном правонарушении должен определяться на основании приобщенных к делу документов, подтверждающих наличие и размеры отнесенных к издержкам затрат.\nРасходы на оплату труда адвоката или иного лица, участвовавшего в производстве по делу в качестве защитника, не отнесены к издержкам по делу об административном правонарушении. Поскольку в случае отказа в привлечении лица к административной ответственности либо удовлетворения его жалобы на постановление о привлечении к административной ответственности этому лицу причиняется вред в связи с расходами на оплату труда лица, оказывавшего юридическую помощь, эти расходы на основании статей 15, 1069, 1070 ГК РФ могут быть взысканы в пользу этого лица за счет средств соответствующей казны (казны Российской Федерации, казны субъекта Российской Федерации). Жалоба на постановление или решение по делу об административном правонарушении не облагается государственной пошлиной."],
["27","Требования о возмещении материального и морального вреда, причиненного незаконным применением мер обеспечения производства по делу об…","","","27. Требования о возмещении материального и морального вреда, причиненного незаконным применением мер обеспечения производства по делу об административном правонарушении (часть 2 статьи 27.1 КоАП РФ) и незаконным привлечением к административной ответственности, подлежат рассмотрению в соответствии с гражданским законодательством в порядке гражданского судопроизводства."],
["28","Учитывая, что изъятие из незаконного владения лица, совершившего административное правонарушение, орудия совершения или предмета административного…","","","28. Учитывая, что изъятие из незаконного владения лица, совершившего административное правонарушение, орудия совершения или предмета административного правонарушения, изъятых из оборота и подлежащих обращению в доход государства или уничтожению, не является конфискацией (часть 3 статьи 3.7 КоАП РФ), судья при вынесении постановления по делу об административном правонарушении в соответствии с частью 3 статьи 29.10 КоАП РФ должен решить вопрос об этих вещах независимо от привлечения лица к административной ответственности, в том числе при вынесении постановления о прекращении производства по делу по любому основанию, указанному в части 1 статьи 29.9 КоАП РФ.\nЕсли данный вопрос не был разрешен судьей при вынесении постановления по делу об административном правонарушении, то этот же судья вправе вынести определение об изъятии орудия совершения или предмета административного правонарушения и обращении его в доход государства. При наличии жалобы либо протеста на постановление судьи этот вопрос может быть решен судьей вышестоящего суда путем изменения постановления без его отмены и направления на новое рассмотрение."],
["29","При вынесении постановления по делу об административном правонарушении судья в исключительных случаях вправе отложить составление мотивированного…","","","29. При вынесении постановления по делу об административном правонарушении судья в исключительных случаях вправе отложить составление мотивированного постановления не более чем на три дня со дня окончания разбирательства дела, за исключением дел об административных правонарушениях, указанных в частях 3 - 5 статьи 29.6 КоАП РФ (часть 1 статьи 29.11 КоАП РФ).\nРезолютивная часть постановления в таких случаях должна быть объявлена немедленно по окончании рассмотрения дела. Днем вынесения постановления следует считать день его составления в полном объеме, а не день оглашения резолютивной части постановления."],
["29.1","Согласно положениям статей 30.3 и 31.1 КоАП РФ постановление по делу об административном правонарушении вступает в законную силу по истечении десяти…","","","29.1. Согласно положениям статей 30.3 и 31.1 КоАП РФ постановление по делу об административном правонарушении вступает в законную силу по истечении десяти суток, а по делам, перечисленным в части 3 статьи 30.3 КоАП РФ, - пяти дней со дня вручения или получения копии постановления, если оно не было обжаловано либо опротестовано.\nПри этом копия постановления по делу об административном правонарушении должна быть вручена под расписку физическому лицу или законному представителю физического лица либо законному представителю юридического лица, в отношении которых оно вынесено, либо выслана указанным лицам в течение трех дней со дня вынесения указанного постановления (часть 2 статьи 29.11 КоАП РФ).\nВ случае, если копия постановления по делу об административном правонарушении, направленная по месту жительства или месту нахождения лица, привлекаемого к административной ответственности, была возвращена судье с отметкой на почтовом извещении (отправлении) об отсутствии этого лица по указанному адресу либо о его уклонении от получения почтового отправления, а также по истечении срока хранения, то постановление вступает в законную силу по истечении десяти суток, а постановления по делам об административных правонарушениях, предусмотренных статьями 5.1 - 5.25, 5.45 - 5.52, 5.56, 5.58 КоАП РФ, - по истечении пяти дней после даты поступления (возвращения) в суд копии данного постановления (статьи 30.3, 31.1 КоАП РФ)."],
["30","В соответствии с пунктом 3 части 1 статьи 30.1 КоАП РФ постановление по делу об административном правонарушении может быть обжаловано в районный суд…","","","30. В соответствии с пунктом 3 части 1 статьи 30.1 КоАП РФ постановление по делу об административном правонарушении может быть обжаловано в районный суд по месту рассмотрения дела, а военнослужащими (гражданами, проходящими военные сборы) - в гарнизонный военный суд (статья 29.5 КоАП РФ).\nПри определении территориальной подсудности дел по жалобам на постановления по делам об административных правонарушениях, вынесенные должностными лицами, необходимо исходить из территории, на которую распространяется юрисдикция должностных лиц, а не из места расположения органа, от имени которого должностным лицом составлен протокол или вынесено постановление по делу об административном правонарушении в порядке, предусмотренном частью 3 статьи 28.6 и статьей 29.10 КоАП РФ. То есть в таких ситуациях территориальная подсудность рассмотрения жалоб на постановления по делам об административных правонарушениях должна определяться местом совершения правонарушения, а не местом нахождения соответствующего органа.\nАналогичный порядок применяется при определении территориальной подсудности рассмотрения жалоб на решения вышестоящих должностных лиц, принятые по результатам рассмотрения жалоб на постановления по делам об административных правонарушениях, вынесенные в порядке, предусмотренном частью 3 статьи 28.6 и статьей 29.10 КоАП РФ."],
["31","В случае пропуска установленного частью 1 статьи 30.3 КоАП РФ срока обжалования постановления по делу об административном правонарушении он может…","","","31. В случае пропуска установленного частью 1 статьи 30.3 КоАП РФ срока обжалования постановления по делу об административном правонарушении он может быть восстановлен по ходатайству лица, подавшего жалобу, или прокурора, принесшего протест (часть 2 статьи 30.3 КоАП РФ, часть 1 статьи 30.10 КоАП РФ), в порядке, предусмотренном статьями 30.2 - 30.8 КоАП РФ, с обязательным извещением указанных лиц. Об отклонении ходатайства о восстановлении срока обжалования постановления по делу об административном правонарушении выносится определение (часть 3 статьи 30.3 КоАП РФ).\nНесмотря на то что КоАП РФ не предусматривает возможности обжалования определения об отклонении ходатайства о восстановлении названного срока, это определение исходя из общих принципов осуществления правосудия может быть обжаловано, поскольку оно исключает возможность дальнейшего движения дела об административном правонарушении, что влечет нарушение права лица, привлеченного к административной ответственности, на защиту.\nХодатайство о восстановлении срока обжалования постановления мирового судьи по делу об административном правонарушении рассматривает судья районного суда, к полномочиям которого относится рассмотрение дела по жалобе на постановление мирового судьи, а ходатайство о восстановлении срока обжалования решения судьи районного суда или гарнизонного военного суда, вынесенное по жалобе на постановление органа, уполномоченного рассматривать дела об административных правонарушениях, в соответствии с частью 2 статьи 30.3 КоАП РФ рассматривается судьей вышестоящего суда (верховного суда республики, краевого, областного суда, суда города федерального значения, автономной области, автономного округа, окружного (флотского) военного суда)."],
["32","Исключен","","","32. Исключен. - Постановление Пленума Верховного Суда РФ от 10.06.2010 N 13."],
["33","Порядок обжалования и вступления в законную силу постановлений и (или) решений по делам об административных правонарушениях зависит от того, каким…","","","33. Порядок обжалования и вступления в законную силу постановлений и (или) решений по делам об административных правонарушениях зависит от того, каким органом рассматривалось дело.\nЕсли дело рассматривалось органом (должностным лицом), уполномоченным рассматривать дела об административных правонарушениях, то его постановление может быть обжаловано в районный суд, а военнослужащими - в гарнизонный военный суд (пункты 2 и 3 части 1 статьи 30.1 КоАП РФ). Решение судьи районного суда или гарнизонного военного суда, принятое по жалобе на такое постановление, может быть обжаловано в соответствии с частями 1 и 2 статьи 30.9 КоАП РФ в вышестоящий суд. Постановление по делу об административном правонарушении, совершенном юридическим лицом или лицом, осуществляющим предпринимательскую деятельность без образования юридического лица, вынесенное органом (должностным лицом), уполномоченным рассматривать дела об административных правонарушениях, или арбитражным судом, согласно части 3 статьи 30.1 КоАП РФ может быть обжаловано в арбитражный суд в соответствии с Арбитражным процессуальным кодексом Российской Федерации и статьями 10, 26, 36 Федерального конституционного закона \"Об арбитражных судах в Российской Федерации\". Постановление по делу об административном правонарушении, совершенном юридическим лицом или индивидуальным предпринимателем, вынесенное судьей суда общей юрисдикции, может быть обжаловано в соответствии с пунктом 1 части 1 статьи 30.1 КоАП РФ в вышестоящий суд общей юрисдикции. При этом необходимо учитывать, что жалобы указанных лиц на постановление о привлечении к административной ответственности, исходя из положений, закрепленных в части 3 статьи 30.1 КоАП РФ и пункте 3 части 1 статьи 29 АПК РФ, подлежат рассмотрению в судах общей юрисдикции, если юридическое лицо или индивидуальный предприниматель привлечены к административной ответственности не в связи с осуществлением указанными лицами предпринимательской и иной экономической деятельности. Например, когда объективная сторона совершенного ими административного правонарушения выражается в действиях (бездействии), направленных на нарушение или невыполнение норм действующего законодательства в сфере санитарно-эпидемиологического благополучия населения, в области охраны окружающей среды и природопользования, безопасности дорожного движения, пожарной безопасности, законодательства о труде и охране труда.\nПодача жалоб и их рассмотрение осуществляются согласно части 3 статьи 30.9 КоАП РФ в порядке, установленном статьями 30.2 - 30.8 этого Кодекса.\nЕсли дело рассматривалось мировым судьей, судьей районного суда или гарнизонного военного суда, то их постановление может быть обжаловано в порядке, установленном статьями 30.2 - 30.8 КоАП РФ, только в вышестоящий суд: соответственно в районный суд либо в верховный суд республики, краевой, областной суд, суд города федерального значения, автономной области, автономного округа, окружной (флотский) военный суд (пункт 1 части 1 статьи 30.1 КоАП РФ).\nВозможность обжалования в таком же порядке решения судьи вышестоящего суда статья 30.9 КоАП РФ не предусматривает, в связи с чем оно вступает в законную силу немедленно после вынесения (пункт 3 статьи 31.1 КоАП РФ).\nВ дальнейшем возможен только пересмотр вступивших в законную силу постановлений и решений по делам об административных правонарушениях в порядке, предусмотренном статьями 30.12 - 30.19 КоАП РФ.\nПоскольку в соответствии с частью 3 статьи 30.12 КоАП РФ право принесения протеста на вступившие в законную силу постановление судьи по делу об административном правонарушении и решение по результатам рассмотрения жалобы или протеста на такое постановление принадлежит прокурорам субъектов Российской Федерации и их заместителям, Генеральному прокурору Российской Федерации и его заместителям, а в отношении военнослужащих и граждан, призванных на военные сборы, - прокурорам военных округов, флотов и приравненным к ним прокурорам, Главному военному прокурору и их заместителям, указанные лица вправе истребовать дела об административных правонарушениях для проверки после вступления постановления или решения в законную силу."],
["33.1","Если в ходе подготовки к рассмотрению жалобы на постановление по делу об административном правонарушении или при рассмотрении такой жалобы лицом,…","","","33.1. Если в ходе подготовки к рассмотрению жалобы на постановление по делу об административном правонарушении или при рассмотрении такой жалобы лицом, подавшим жалобу, будет заявлено ходатайство об отказе от жалобы, судье следует обсудить указанное ходатайство и в случае его удовлетворения вынести определение о прекращении производства по жалобе (пункт 2 статьи 30.4, пункт 6 части 2 статьи 30.6, статья 29.12 КоАП РФ)."],
["33.2","Разрешая жалобы на постановления по делам об административных правонарушениях, необходимо учитывать положения части 2 статьи 1.7 КоАП РФ, в…","","","33.2. Разрешая жалобы на постановления по делам об административных правонарушениях, необходимо учитывать положения части 2 статьи 1.7 КоАП РФ, в соответствии с которой закон, смягчающий или отменяющий административную ответственность за административное правонарушение либо иным образом улучшающий положение лица, совершившего административное правонарушение, имеет обратную силу, то есть распространяется и на лицо, которое совершило административное правонарушение до вступления такого закона в силу при условии, что постановление о назначении административного наказания не исполнено."],
["34","При решении вопроса о принятии к рассмотрению надзорной жалобы или протеста судье, правомочному пересматривать в порядке надзора вступившие в…","","","34. При решении вопроса о принятии к рассмотрению надзорной жалобы или протеста судье, правомочному пересматривать в порядке надзора вступившие в законную силу постановление по делу об административном правонарушении, решение по результатам рассмотрения жалоб и протестов (части 2 и 3 статьи 30.13 КоАП РФ), необходимо в каждом случае выяснять, соблюдены ли при подаче жалобы, принесении протеста требования, предусмотренные статьей 30.14 и частью 4 статьи 30.16 КоАП РФ.\nПри несоблюдении заявителем или прокурором требований, предъявляемых статьей 30.14 КоАП РФ к содержанию жалобы, протеста, а также при отсутствии копий всех перечисленных в этой норме документов, подлежащих приобщению к жалобе, протесту, либо в случае, когда повторные жалоба, протест поданы, принесены по тем же основаниям, что и первичные, судья возвращает жалобу, протест с указанием в сопроводительном письме на допущенные нарушения. При этом не подлежат возвращению первичный протест, принесенный по тем же основаниям, что и жалоба, а также первичная жалоба, поданная по тем же основаниям, что и протест.\nЖалоба или протест подлежат возвращению и в случае их подачи, принесения лицами, не указанными в статье 30.12 КоАП РФ, а также когда обжалуются, опротестовываются вступившие в законную силу акты несудебных органов и должностных лиц, которые не являлись предметом судебного рассмотрения (статья 30.1 КоАП РФ).\nЕсли судья придет к выводу о соответствии жалобы, протеста требованиям закона, он согласно частям 1 и 2 статьи 30.15 КоАП РФ обязан вынести определение об их принятии к рассмотрению в порядке надзора и известить об этом лицо, в отношении которого ведется производство по делу об административном правонарушении, а также потерпевшего и предоставить указанным лицам возможность ознакомиться с жалобой, протестом и подать возражения на них.\nРассмотрение надзорных жалоб и протестов на вступившие в законную силу постановления и (или) решения по делам об административных правонарушениях не требует проведения судебного заседания, поскольку это не предусмотрено КоАП РФ.\nЕсли у председателя или заместителя председателя соответствующего суда возникнут сомнения в законности обжалованного, опротестованного постановления и (или) решения по делу об административном правонарушении, он вправе истребовать дело для проверки. При этом в соответствии с частью 2 статьи 30.16 КоАП РФ указанные лица в интересах законности могут проверить дело в полном объеме.\nПо результатам рассмотрения жалобы председатель или заместитель председателя соответствующего суда выносит одно из постановлений, перечисленных в статье 30.17 КоАП РФ. Копия постановления направляется прокурору и (или) лицу, подавшему жалобу."],
["35","Обращение постановления по делу об административном правонарушении к исполнению возлагается на судью, вынесшего постановление (часть 1 статьи 31.3…","","","35. Обращение постановления по делу об административном правонарушении к исполнению возлагается на судью, вынесшего постановление (часть 1 статьи 31.3 КоАП РФ). Постановление по делу об административном правонарушении подлежит исполнению с момента его вступления в законную силу (статья 31.1 КоАП РФ), за исключением постановления об административном аресте, которое подлежит немедленному исполнению (часть 1 статьи 32.8 КоАП РФ). Исполнение постановления о назначении наказания в виде предупреждения осуществляется судьей, вынесшим постановление (статья 32.1 КоАП РФ). В остальных случаях постановление направляется судьей для исполнения управомоченному органу (эти органы определены в статьях о порядке исполнения отдельных видов наказания). Если постановление о наложении административного наказания не было обжаловано, оно направляется судьей управомоченному органу в трехдневный срок со дня вступления в силу, а если обжаловано - в течение трех дней со дня поступления решения по жалобе, протесту из суда, вынесшего решение."],
["36","При приведении постановления по делу в исполнение необходимо учитывать, что в соответствии с частью 1 статьи 31.9 КоАП РФ постановление о назначении…","","","36. При приведении постановления по делу в исполнение необходимо учитывать, что в соответствии с частью 1 статьи 31.9 КоАП РФ постановление о назначении административного наказания не подлежит исполнению в случае, если оно не было приведено в исполнение в течение двух лет со дня его вступления в законную силу.\nПри исчислении срока давности исполнения постановления о назначении административного наказания следует иметь в виду, что частями 2 - 4 статьи 31.9 КоАП РФ предусмотрены случаи, когда течение этого срока прерывается либо приостанавливается.\nКроме того, необходимо учитывать, что исполнение постановления по делу об административном правонарушении подлежит прекращению на основании пункта 4 статьи 31.7 КоАП РФ по истечении срока давности исполнения постановления, установленного частью 1 статьи 31.9 КоАП РФ, независимо от того, что исполнение не производилось либо произведено не полностью."],
["37","Приостановление исполнения вступившего в законную силу постановления по делу об административном правонарушении в связи с подачей жалобы лицами,…","","","37. Приостановление исполнения вступившего в законную силу постановления по делу об административном правонарушении в связи с подачей жалобы лицами, перечисленными в статьях 25.1 - 25.5 КоАП РФ, недопустимо, поскольку частью 1 статьи 31.6 КоАП РФ такая возможность предусмотрена лишь в случае принесения прокурором протеста по делу об административном правонарушении до рассмотрения протеста.\nПредседатель Верховного Суда Российской Федерации В.М.ЛЕБЕДЕВ Секретарь Пленума, судья Верховного Суда Российской Федерации В.В.ДЕМИДОВ"]
];
